package cn.gmiya.malodylink;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.Drawable;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.io.File;
public final class GameplayActivity extends Activity {
 private View controls,heading;private final Runnable hideControls=()->{if(this.running){controls.setVisibility(View.GONE);heading.setVisibility(View.GONE);}};
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler ui=new Handler(Looper.getMainLooper());private GameplayView stage;private TextView status,time;private SeekBar seek;private ImageButton play,restart;private GameplayChart chart;private MediaPlayer media;private File musicFile;private boolean running,ready,seeking,started,dragging,dead;private double cursor,anchor;private long clock;private AudioManager audio;private AudioFocusRequest focus;
 public static void open(Activity a,int cid){a.startActivity(new Intent(a,GameplayActivity.class).putExtra("cid",cid));}
 @Override public void onCreate(Bundle state){super.onCreate(state);setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(0xff06111b);getWindow().setNavigationBarColor(0xff06111b);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);audio=(AudioManager)getSystemService(AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).build()).setOnAudioFocusChangeListener(change->{if(change<0)pause();},ui).build();
 FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff06111b);stage=new GameplayView(this);root.addView(stage,new FrameLayout.LayoutParams(-1,-1));
 LinearLayout header=AppUi.column(this,8);header.setOrientation(LinearLayout.HORIZONTAL);header.setGravity(Gravity.CENTER_VERTICAL);header.setBackgroundColor(0x99081118);header.addView(button("返回",3,this::finish));LinearLayout labels=AppUi.column(this,0);labels.addView(AppUi.text(this,"自动游玩预览 · AUTO",14,0xffeefaff,true));status=AppUi.text(this,"正在读取谱面…",11,0xffb1ccda,false);status.setSingleLine(true);labels.addView(status);header.addView(labels,new LinearLayout.LayoutParams(0,-2,1));heading=header;root.addView(header,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));
 LinearLayout panel=AppUi.column(this,8);panel.setBackgroundColor(0xe6081520);time=AppUi.text(this,"",11,0xffd5edf9,false);panel.addView(time);seek=new SeekBar(this);seek.setMax(10000);seek.setEnabled(false);panel.addView(seek,new LinearLayout.LayoutParams(-1,AppUi.dp(this,28)));LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);play=button("播放／暂停",0,()->{if(running)pause();else start();});restart=button("从头播放",2,()->{pause();jump(chart.first);});play.setEnabled(false);restart.setEnabled(false);actions.addView(play);actions.addView(restart);TextView flow=AppUi.text(this,"",12,0xffcbf9ef,true);flow.setMinWidth(AppUi.dp(this,82));actions.addView(flow);CheckBox scrollSwitch=new CheckBox(this);scrollSwitch.setText("谱面变速");scrollSwitch.setTextSize(11);scrollSwitch.setTextColor(0xffcbf9ef);scrollSwitch.setButtonTintList(android.content.res.ColorStateList.valueOf(0xff91ddd4));scrollSwitch.setContentDescription("跟随谱面流速变化，关闭时为恒速");scrollSwitch.setOnCheckedChangeListener((v,on)->{stage.followScroll=on;stage.invalidate();});actions.addView(scrollSwitch);SeekBar flowBar=new SeekBar(this);flowBar.setMax(115);flowBar.setMinimumHeight(AppUi.dp(this,48));flowBar.setContentDescription("下落流速，0.5倍至12倍");flowBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){ui.removeCallbacks(hideControls);}public void onStopTrackingTouch(SeekBar b){getSharedPreferences("gameplay",0).edit().putInt("speed",b.getProgress()).apply();if(running)ui.postDelayed(hideControls,2000);}public void onProgressChanged(SeekBar b,int v,boolean user){double speed=.5+v*.1;stage.approach=2/speed;flow.setText(String.format(Locale.ROOT,"流速 %.1f×",speed));stage.invalidate();}});flowBar.setProgress(getSharedPreferences("gameplay",0).getInt("speed",15));actions.addView(flowBar,new LinearLayout.LayoutParams(0,AppUi.dp(this,48),1));panel.addView(actions);controls=panel;root.addView(panel,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));
 stage.setOnClickListener(v->{boolean show=controls.getVisibility()!=View.VISIBLE;controls.setVisibility(show?View.VISIBLE:View.GONE);heading.setVisibility(show?View.VISIBLE:View.GONE);ui.removeCallbacks(hideControls);});setContentView(root);root.setOnApplyWindowInsetsListener((v,in)->{int l=in.getSystemWindowInsetLeft(),rr=in.getSystemWindowInsetRight();header.setPadding(l+AppUi.dp(this,8),AppUi.dp(this,4),rr+AppUi.dp(this,8),AppUi.dp(this,4));panel.setPadding(l+AppUi.dp(this,12),AppUi.dp(this,4),rr+AppUi.dp(this,12),AppUi.dp(this,6));return in;});
 seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){boolean resume;public void onStartTrackingTouch(SeekBar s){resume=running;pause();dragging=true;}public void onProgressChanged(SeekBar s,int v,boolean user){if(user&&chart!=null){cursor=chart.first+(chart.end-chart.first)*v/10000;draw();}}public void onStopTrackingTouch(SeekBar s){dragging=false;jump(cursor);if(resume)start();}});
 io.execute(()->{try{Engine engine=new Engine(this);JSONObject row=null;for(int i=0;i<engine.charts().length();i++){JSONObject c=engine.charts().getJSONObject(i);if(c.optInt("cid")==getIntent().getIntExtra("cid",0))row=c;}if(row==null)throw new Exception("谱库未找到此谱面");String name=row.optString("title");final JSONObject selected=row;GameplaySource.Loaded data=GameplaySource.load(this,engine,row,s->ui.post(()->{if(!dead)status.setText(s);}));ui.post(()->{if(dead){if(data.music!=null)data.music.delete();return;}chart=data.chart;stage.chart=chart;musicFile=data.music;cursor=chart.first;io.execute(()->{try{byte[] art=ServerArtwork.get(this,selected.optInt("cid"),selected.optString("server_hash"));android.graphics.Bitmap bg=android.graphics.BitmapFactory.decodeByteArray(art,0,art.length);ui.post(()->{if(!dead){stage.background=bg;stage.invalidate();}else if(bg!=null)bg.recycle();});}catch(Exception optional){}});status.setText(name+" · "+chart.keys+"K · "+data.source+"\n"+data.warning+(chart.effects?" · 部分皮肤效果暂未模拟":""));if(musicFile==null){enable();return;}try{media=new MediaPlayer();media.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());media.setDataSource(musicFile.getAbsolutePath());media.setOnPreparedListener(m->{ready=true;status.append(" · 原曲已加载");enable();});media.setOnSeekCompleteListener(m->{seeking=false;if(running&&!dead){m.start();started=true;anchor=m.getCurrentPosition()/1000.0+chart.audioStart;clock=SystemClock.elapsedRealtime();}});media.setOnErrorListener((m,w,e)->{pause();m.release();media=null;ready=false;status.append(" · 音乐解码失败，静音预览");enable();return true;});media.prepareAsync();}catch(Exception e){if(media!=null)media.release();media=null;status.append(" · 音乐无法播放，静音预览");enable();}});}catch(Exception e){ui.post(()->{if(!dead)status.setText(e.getMessage());});}});
 }
 void enable(){seek.setEnabled(true);play.setEnabled(true);restart.setEnabled(true);draw();}
 double now(){return running?anchor+(SystemClock.elapsedRealtime()-clock)/1000.0:cursor;}
 void start(){if(chart==null||dead||running)return;if(media!=null&&audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){status.append(" · 暂未取得音乐播放权限");return;}if(cursor>=chart.end)jump(chart.first);anchor=cursor;clock=SystemClock.elapsedRealtime();running=true;ui.removeCallbacks(hideControls);ui.postDelayed(hideControls,2000);play.setImageDrawable(new Icon(1));ui.removeCallbacks(tick);ui.post(tick);}
 void pause(){if(running)cursor=now();running=false;ui.removeCallbacks(tick);ui.removeCallbacks(hideControls);if(controls!=null){controls.setVisibility(View.VISIBLE);heading.setVisibility(View.VISIBLE);}if(media!=null&&ready)try{media.pause();}catch(IllegalStateException ignored){}started=false;if(play!=null)play.setImageDrawable(new Icon(0));if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);}
 void jump(double t){if(chart==null)return;cursor=Math.max(chart.first,Math.min(chart.end,t));anchor=cursor;clock=SystemClock.elapsedRealtime();started=false;draw();}
 void draw(){stage.time=cursor;stage.invalidate();if(!dragging)seek.setProgress((int)(10000*(cursor-chart.first)/(chart.end-chart.first)));time.setText(String.format(Locale.ROOT,"%02d:%02d / %02d:%02d · AUTO · 不记录成绩",(int)Math.max(0,cursor)/60,(int)Math.max(0,cursor)%60,(int)chart.end/60,(int)chart.end%60));}
 private final Runnable tick=()->frame();
 void frame(){if(!running||dead)return;double t=now();if(media!=null&&ready&&t>=chart.audioStart&&!started&&!seeking){if(t-chart.audioStart>=media.getDuration()/1000.0)started=true;else{seeking=true;media.seekTo(Math.max(0,Math.round((t-chart.audioStart)*1000)),MediaPlayer.SEEK_CLOSEST);}}if(media!=null&&ready&&started&&media.isPlaying()){MediaTimestamp stamp=media.getTimestamp();if(stamp!=null){double at=stamp.getAnchorMediaTimeUs()/1000000.0+(System.nanoTime()-stamp.getAnchorSytemNanoTime())/1000000000.0*stamp.getMediaClockRate()+chart.audioStart;anchor=at;clock=SystemClock.elapsedRealtime();t=at;}}cursor=t;draw();if(t>=chart.end)pause();else ui.postDelayed(tick,16);}
 ImageButton button(String label,int kind,Runnable action){ImageButton b=new ImageButton(this);b.setImageDrawable(new Icon(kind));b.setContentDescription(label);b.setTooltipText(label);b.setBackground(AppUi.background(this,0xff19333f));int s=AppUi.dp(this,48);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(s,s);lp.setMargins(0,0,AppUi.dp(this,12),0);b.setLayoutParams(lp);b.setOnClickListener(v->action.run());return b;}
 static class Icon extends Drawable{final int kind;final Paint p=new Paint(3);Icon(int k){kind=k;}public void draw(Canvas canvas){canvas.save();canvas.translate(getBounds().left,getBounds().top);canvas.scale(getBounds().width()/48f,getBounds().height()/48f);p.setColor(0xffb8f8ef);p.setStrokeWidth(2.5f);p.setStyle(Paint.Style.STROKE);if(kind==0){Path t=new Path();t.moveTo(18,13);t.lineTo(34,24);t.lineTo(18,35);t.close();canvas.drawPath(t,p);}else if(kind==1){canvas.drawLine(19,14,19,34,p);canvas.drawLine(29,14,29,34,p);}else if(kind==2){canvas.drawArc(13,13,35,35,-70,285,false,p);canvas.drawLine(13,13,13,23,p);canvas.drawLine(13,23,23,23,p);}else{canvas.drawLine(29,13,18,24,p);canvas.drawLine(18,24,29,35,p);}canvas.restore();}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 @Override protected void onPause(){pause();super.onPause();}
 @Override protected void onDestroy(){dead=true;pause();ui.removeCallbacksAndMessages(null);io.shutdownNow();if(media!=null){media.release();media=null;}if(musicFile!=null)musicFile.delete();stage.release();super.onDestroy();}
}
